class FileCache:
    def __init__(self, strategy=None):
        self._lock = strategy or threading.RLock()   # Lock, RLock, Semaphore, ...

    def find(self, path):
        with self._lock:            # Scoped Locking: released on every exit path
            return self._find(path)  # assumes the lock is held

class NullLock:                      # no-op policy for single-threaded builds
    def __enter__(self): return self
    def __exit__(self, *exc): return False
